struct Collision {
    vec3 position;
    vec3 side;
};

vec3 minIndicator(vec3 v) {
    if (v.x <= v.y && v.x <= v.z) {
        return vec3(1.0, 0.0, 0.0);
    }
    if (v.y <= v.z) {
        return vec3(0.0, 1.0, 0.0);
    }
    return vec3(0.0, 0.0, 1.0);
}

Collision nextHit(vec3 start, vec3 dir) {
    start += dir * 0.0001;  // slight bias to avoid repeated hits
    vec3 dirsign = sign(dir);
    vec3 candidates = round(start + dirsign * 0.5);
    vec3 timeToHit = (candidates - start) / dir;
    vec3 indicator = minIndicator(timeToHit);
    float time = min(timeToHit.x, min(timeToHit.y, timeToHit.z));
    Collision result;
    result.position = start + dir * time;
    result.side = indicator;
    return result;
}

vec3 faceCenter(Collision c) {
    // todo
    vec3 p = c.position;
    return vec3(round(p.x), round(p.y), round(p.z));
}

vec3 blockCenter(Collision c) {
    return c.position;
}

float gridDistance (vec3 xyz) {
    vec3 d = abs(xyz - round(xyz));
    return 100.0 * (d.x + 0.03) * (d.y + 0.03) * (d.z + 0.03);
}

vec3 path(float z) {
  float x = 6.0 * sin(z * 0.1);
  float y = 6.0 * cos(z * 0.1);

  x += 3.0 * sin(z * 0.2 + 0.5);

  return vec3(x, y, z);
}

bool nearPath(vec3 coord) {
    vec3 pp = round(path(coord.z));
    return abs(coord.x - pp.x) < 1.1 && abs(coord.y - pp.y) < 1.1;
}

vec4 colorizePoint(vec3 coord) {
    if (nearPath(coord) || nearPath(vec3(-coord.x, coord.y, coord.z))) {
        return vec4(0.0, 0.0, 0.0, 0.0);
    }

    /*
    if (abs(coord.y) < 2.0) {
        return vec4(0.0, 0.0, 0.0, 0.0);
    }
    if (coord.y > -2.0 && abs(coord.x) < 2.0) {
        return vec4(0.0, 0.0, 0.0, 0.0);
    }
    */


    // create wave layers
    float n = 0.0;
    float speed = 0.1;
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(0.9390406643392357, -0.13591148351201948, 0.3158016772705439)));
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(-0.2913156813937904, 0.5056202493940141, -0.8120857942217722)));
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(-0.6399178240853491, 0.7394662306857567, 0.2090331841915812)));
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(0.9724564044055869, 0.02247534267671038, -0.2319987079751134)));
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(0.9268517643295816, -0.12705147981431308, -0.35327571164196214)));
    n += sin(speed * iTime + 2.0 * dot(coord, vec3(-0.4253067166118151, -0.4211350196064697, -0.8010989277648145)));

    // result
    float r = pow(0.7 + 0.7 * sin(1.0 * n), 1.4);
    float g = pow(0.5 + 0.5 * sin(2.0 * n), 1.2);
    float b = pow(0.55 + 0.55 * sin(3.0 * n), 1.0);
    float a = pow(r*r+g*g+b*b, 0.5);
    return vec4(r, g, b, a * 0.5 + 0.3);
}

vec4 shine(vec4 col) {
    float b = max(max(col.r, col.g), col.b);
    float over = max(b - 1.0, 0.0);
    return vec4(col.r + over, col.g + over, col.b + over, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // geometric mean of the side lengths
    float imSize = sqrt(iResolution.x * iResolution.y);

    // Normalized pixel coordinates
    vec2 centeredCoord = fragCoord - 0.5 * iResolution.xy;
    vec2 normalizedCoord = centeredCoord / imSize;
    vec2 coord = 1.0 * normalizedCoord;
    float z = iTime * 3.0;
    vec3 camera = path(z);

    vec3 ray = vec3(coord.x, coord.y, 0.3);
    ray /= length(ray);

    vec4 result = vec4(0.0, 0.0, 0.0, 0.0);
    float alphaLeft = 1.0;
    Collision hit;
    hit.position = camera;
    hit.side = vec3(1.0, 1.0, 1.0);

    for (int i = 0; i < 30; i++) {
        hit = nextHit(hit.position, ray);
        vec4 col1 = colorizePoint(hit.position);
        vec4 col2 = colorizePoint(faceCenter(hit));
        vec4 rgba = 0.5 * (col1 + col2);
        rgba = max(rgba, vec4(0.0, 0.0, 0.0, 0.0));
        float aa = min(rgba.a * alphaLeft, 1.0);
        alphaLeft -= aa;
        result += rgba * aa;
    }

    // Output to screen
    fragColor = shine(result);
    fragColor = min(fragColor, vec4(1.0, 1.0, 1.0, 1.0));
    fragColor *= 0.75;
}
